#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <inttypes.h>
typedef struct Node {int64_t value; struct Node *next;} Node;
static int64_t fib(int64_t n){return n<2?n:fib(n-1)+fib(n-2);}
static int64_t run(int64_t n){(void)n; return fib(n);}
int main(void){volatile int64_t input=35; printf("%" PRId64 "\n",run(input));return 0;}

