#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <inttypes.h>
typedef struct Node {int64_t value; struct Node *next;} Node;
static int64_t run(int64_t n){(void)n; Node *pool=malloc((size_t)n*2*sizeof(Node)); if(!pool)exit(71); Node *xs=0,*ys=0; int64_t k=0; for(int64_t i=n;i>0;--i){pool[k]=(Node){i,xs};xs=&pool[k++];} for(Node *p=xs;p;p=p->next){pool[k]=(Node){p->value*3+1,ys};ys=&pool[k++];} int64_t a=0; for(Node *p=ys;p;p=p->next)a+=p->value; free(pool); return a;}
int main(void){volatile int64_t input=500000; printf("%" PRId64 "\n",run(input));return 0;}
